WITH base AS (SELECT *, CASE WHEN location = 'Singapore' THEN 1 ELSE 0 END is_singapore FROM departments WHERE dept_name != 'Legal' AND location NOT IN ('London', 'Berlin', 'Tokyo') AND location NOT IN ('Chiang Mai', 'Bangkok')), Summary AS (SELECT dept_name, CASE WHEN is_singapore >= 90 THEN 'high' WHEN is_singapore >= 32 THEN 'mid' ELSE 'low' END is_singapore_bucket, ROUND((100 * SUM(CASE WHEN dept_name = 'Finance' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_finance, COUNT(*) total_count FROM base GROUP BY dept_name, CASE WHEN is_singapore >= 90 THEN 'high' WHEN is_singapore >= 32 THEN 'mid' ELSE 'low' END) SELECT * FROM Summary;
